<script setup>
import{verifyServer}from'./verify.js';
import{computed,onBeforeUnmount,onMounted,ref,toRaw}from'vue';import dayjs from'dayjs';import CircleProgress from'./CircleProgress.vue';import{createServerStore,createServerReader,validateServer,monitorArgs,metrics,maskIp}from'./server-model.js';import{platforms,platformIcon,osIcon}from'./icons.js';
const props=defineProps({host:Object,stored:Object,settings:Object});const version=ref(0),message=ref(''),busy=ref(false),revealed=ref({}),editDialog=ref(),syncDialog=ref(),themeDialog=ref(),deleteDialog=ref(),pendingDelete=ref(null),draft=ref({api:{url:"",token:"",interval:10}}),sync=ref({url:'',token:''}),theme=ref({...props.settings}),context=ref(null);let alive=true,timer,cursor=0;
const model=createServerStore(props.stored,value=>props.host.preview?Promise.resolve():props.host.request('storage.set',value),()=>version.value++);
const reader=createServerReader(args=>props.host.request('server.request',args),()=>version.value++);
const config=computed(()=>{version.value;return model.snapshot();});const rows=computed(()=>{version.value;return config.value.servers.map(server=>({server,reading:reader.get(server,config.value.master),view:metrics(reader.get(server,config.value.master),server.api.interval)}));});
function applyTheme(value){for(const[key,fallback]of[['background','#000000'],['color','#ffffff'],['borderColor','#333333']])document.documentElement.style.setProperty('--widget-'+key,CSS.supports('color',value[key])?value[key]:fallback);document.documentElement.style.setProperty('--widget-font-size',value.fontSize+'px');document.documentElement.style.setProperty('--radius',value.radius+'px');}
applyTheme(props.settings);
function errorText(error){return String(error?.message||error);}
function tick(){if(!alive||props.host.preview)return;const servers=config.value.servers;reader.retain(servers.map(server=>server.id));for(let i=0;i<servers.length;i++)void reader.refresh(servers[(cursor+i)%servers.length],config.value.master);if(servers.length)cursor=(cursor+4)%servers.length;version.value++;}
onMounted(async()=>{await props.host.ready();if(!alive)return;tick();timer=setInterval(tick,1000);void verifyServer({host:props.host,model,getState:()=>({alive,rows:rows.value,draft:draft.value,sync:sync.value,theme:theme.value,busy:busy.value,message:message.value}),actions:{openEdit,openSync,syncServers,openTheme,saveTheme,closeDialogs:()=>{for(const dialog of [editDialog,syncDialog,themeDialog,deleteDialog])dialog.value?.close();}}});});onBeforeUnmount(()=>{alive=false;clearInterval(timer);reader.dispose();model.dispose();});
function openEdit(server){if(props.host.preview||busy.value)return;context.value=null;const source=server?structuredClone(toRaw(server)):{name:'',ip:'',platform:'Other',region:'',note:'',intranetIp:'',createTime:new Date().toISOString(),expireTime:dayjs().add(1,'year').toISOString(),api:{url:'',token:'',interval:10}};source.createDate=dayjs(source.createTime).isValid()?dayjs(source.createTime).format('YYYY-MM-DD'):'';source.expireDate=source.expireTime&&dayjs(source.expireTime).isValid()?dayjs(source.expireTime).format('YYYY-MM-DD'):'';draft.value=source;message.value='';editDialog.value.showModal();}
function date(value){if(!value)return undefined;const parsed=dayjs(value);if(!parsed.isValid()||parsed.format('YYYY-MM-DD')!==value)throw new Error('日期无效');return parsed.toISOString();}
async function push(){const state=model.snapshot();if(!state.master.url)return '';try{await props.host.request('server.request',{kind:'push',connection:state.master,servers:state.servers});return '；同步请求已被主服务器接受';}catch(error){return '；主服务器同步未完成：'+errorText(error);}}
async function saveServer(){if(busy.value||props.host.preview)return;busy.value=true;try{const{createDate,expireDate,...rest}=structuredClone(toRaw(draft.value)),server=validateServer({...rest,id:rest.id||crypto.randomUUID(),name:rest.name.trim(),createTime:date(createDate)||new Date().toISOString(),expireTime:date(expireDate),api:{...rest.api,interval:Number(rest.api.interval)}});const result=await props.host.request('server.request',monitorArgs('info',server,config.value.master));if(!alive)return;server.cpu=result.data.cpu;server.memery=result.data.mem;server.os=result.data.osInfo;await model.save(server);if(!alive)return;editDialog.value.close();message.value='本地配置已保存'+await push();tick();}catch(error){if(alive)message.value='保存未完成：'+errorText(error);}finally{if(alive)busy.value=false;}}
async function removeServer(){if(busy.value||!draft.value.id||props.host.preview)return;const id=pendingDelete.value;if(!id)return;busy.value=true;try{await model.remove(id);if(!alive)return;deleteDialog.value.close();editDialog.value.close();pendingDelete.value=null;message.value='本地服务器已移除'+await push();reader.retain(model.snapshot().servers.map(server=>server.id));}catch(error){if(alive)message.value='移除未完成：'+errorText(error);}finally{if(alive)busy.value=false;}}
function openSync(){if(props.host.preview||busy.value)return;sync.value=structuredClone(config.value.master);message.value='';syncDialog.value.showModal();}
async function syncServers(kind){if(props.host.preview||busy.value)return;busy.value=true;let committed=false;try{await model.setMaster(structuredClone(toRaw(sync.value)));committed=true;const current=model.snapshot(),revision=model.revision;if(!current.master.url)throw new Error('请填写主服务器地址和令牌');if(kind==='pull'){const result=await props.host.request('server.request',{kind:'pull',connection:current.master});if(!alive)return;await model.merge(result.data,revision);message.value='配置已拉取并保存，保留本地其他服务器';tick();}else{await props.host.request('server.request',{kind:'push',connection:current.master,servers:current.servers});if(alive)message.value='同步请求已被主服务器接受';}}catch(error){if(alive)message.value=(committed?'主服务器配置已保存；':'')+'同步未完成：'+errorText(error);}finally{if(alive)busy.value=false;}}
async function clearMaster(){if(busy.value)return;busy.value=true;try{await model.setMaster({url:'',token:''});sync.value={url:'',token:''};message.value='已清除主服务器，后续直接读取各服务';tick();}catch(error){message.value=errorText(error);}finally{busy.value=false;}}
async function copy(server){revealed.value[server.id]=!revealed.value[server.id];try{await navigator.clipboard.writeText(server.ip);if(alive)message.value='IP已复制';}catch(error){if(alive)message.value='未能复制IP：'+errorText(error);}}
function expires(server){const at=dayjs(server.expireTime);return server.expireTime&&at.isValid()?at.diff(dayjs(),'day')+'天到期':'';}
function openTheme(){theme.value={...props.settings};themeDialog.value.showModal();}
async function saveTheme(){if(busy.value||props.host.preview)return;busy.value=true;try{const settings=await props.host.request('settings.update',{...theme.value,fontSize:Number(theme.value.fontSize),radius:Number(theme.value.radius)});if(!alive)return;Object.assign(props.settings,settings);applyTheme(settings);themeDialog.value.close();message.value='外观已保存';}catch(error){if(alive)message.value='外观未保存：'+errorText(error);}finally{if(alive)busy.value=false;}}
function menu(event){if(props.host.preview||busy.value)return;event.preventDefault();context.value={x:Math.min(event.clientX,innerWidth-140),y:Math.min(event.clientY,innerHeight-40)};}
</script>
<template><main class="widget" @contextmenu="menu" @click="context=null"><header class="heading"><h1>服务器监控</h1><span></span><button title="同步设置" aria-label="同步设置" :disabled="host.preview||busy" @click="openSync">⇩</button><button title="添加服务器" aria-label="添加服务器" :disabled="host.preview||busy" @click="openEdit()">⊞</button><button class="theme-button" title="外观设置" aria-label="外观设置" :disabled="host.preview||busy" @click="openTheme">⚙</button></header>
<section class="servers"><article v-for="{server,view,reading} in rows" :key="server.id" class="server"><div class="server-header"><button class="name" :disabled="host.preview||busy" :title="server.note||server.name" @click="openEdit(server)"><img :src="platformIcon(server.platform)" alt=""><span>{{server.name}}</span><span class="pencil">✎</span></button><button :disabled="host.preview" :title="'点击复制IP并切换显示'" @click="copy(server)">{{revealed[server.id]?server.ip:maskIp(server.ip)}} ▢</button></div><hr><div class="gauges"><div><span>负载</span><CircleProgress :progress="view.cpu===null?null:view.cpu/100"/><small>{{server.cpu?.cores??'—'}}/{{server.cpu?.processors??'—'}}</small></div><div><span>内存</span><CircleProgress :progress="view.memory===null?null:view.memory/100"/><small>{{view.memoryText}}</small></div><div><span>磁盘</span><CircleProgress :progress="view.disk===null?null:view.disk/100"/><small>{{view.diskText}}</small></div></div><hr><footer class="server-footer"><span v-if="server.os" class="os"><img :src="osIcon(server.os.distro)" alt="">{{server.os.distro}} {{server.os.release}} {{server.os.arch}}</span><span v-else>系统信息未提供</span><span class="expiry">{{expires(server)}}</span></footer><p class="reading-status" :class="{stale:view.stale||reading.error}" :title="server.api.url">{{view.status}}</p></article><div v-if="!rows.length" class="empty">尚未添加服务器<button :disabled="host.preview||busy" @click="openEdit()">添加服务器</button></div></section><output class="status" role="status">{{host.preview?'预览 · 不连接服务':busy?'正在处理，请稍候…':message||model.state.error}}</output>
<menu v-if="context" :style="{left:context.x+'px',top:context.y+'px'}" class="context"><button @click.stop="openEdit()">添加服务器</button></menu>
<dialog ref="editDialog" @cancel="busy&&$event.preventDefault()"><form @submit.prevent="saveServer"><h2>服务器编辑</h2><label>名称<input v-model="draft.name" maxlength="30" required></label><label>IP地址<input v-model="draft.ip" required></label><label>云平台<input v-model="draft.platform" list="platforms"><datalist id="platforms"><option v-for="name in platforms" :key="name" :value="name"/></datalist></label><label>区域<input v-model="draft.region"></label><label>创建日期<input v-model="draft.createDate" type="date"></label><label>到期日期<input v-model="draft.expireDate" type="date"></label><label>内网IP<input v-model="draft.intranetIp"></label><label>备注<textarea v-model="draft.note" maxlength="16384"></textarea></label><h3>监控服务器地址</h3><label>服务地址<input v-model="draft.api.url" placeholder="http://127.0.0.1:5549/api/monitor" required></label><label>Token<input v-model="draft.api.token" type="password" autocomplete="off" required></label><label>刷新间隔（秒）<input v-model="draft.api.interval" type="number" min="1" max="3600" required></label><div class="actions"><button v-if="draft.id" type="button" data-delete :disabled="busy" @click="pendingDelete=draft.id;deleteDialog.showModal()">删除</button><button type="submit" :disabled="busy">保存</button><button type="button" :disabled="busy" @click="editDialog.close()">关闭</button></div><p class="feedback">{{message}}</p></form></dialog>
<dialog ref="syncDialog" @cancel="busy&&$event.preventDefault()"><form @submit.prevent="syncServers('pull')"><h2>同步设置</h2><label>服务地址<input v-model="sync.url" placeholder="http://127.0.0.1:5549/api/monitor"></label><label>Token<input v-model="sync.token" type="password" autocomplete="off"></label><p class="help">上传及保存、删除后的同步包含服务器配置和连接令牌，仅发送到这里指定的主服务器。</p><div class="actions"><button type="submit" :disabled="busy">拉取配置</button><button type="button" :disabled="busy" @click="syncServers('push')">上传配置</button><button type="button" :disabled="busy" @click="clearMaster">清除同步</button><button type="button" :disabled="busy" @click="syncDialog.close()">关闭</button></div><p class="feedback">{{message}}</p></form></dialog>
<dialog ref="deleteDialog" @cancel="busy&&$event.preventDefault()"><form @submit.prevent="removeServer"><h2>确定要删除吗？</h2><p>{{draft.name}}：{{draft.ip}}</p><div class="actions"><button type="submit" :disabled="busy">确定删除</button><button type="button" :disabled="busy" @click="deleteDialog.close()">取消</button></div><p class="feedback">{{message}}</p></form></dialog>
<dialog ref="themeDialog" @cancel="busy&&$event.preventDefault()"><form @submit.prevent="saveTheme"><h2>外观设置</h2><label>背景颜色<input v-model="theme.background" type="color"></label><label>文字颜色<input v-model="theme.color" type="color"></label><label>边框颜色<input v-model="theme.borderColor" type="color"></label><label>字体大小<input v-model="theme.fontSize" type="number" min="12" max="28" required></label><label>圆角<input v-model="theme.radius" type="number" min="0" max="60" required></label><div class="actions"><button type="submit" :disabled="host.preview||busy">保存</button><button type="button" :disabled="busy" @click="themeDialog.close()">关闭</button></div><p class="feedback">{{message}}</p></form></dialog></main></template>
